package com.aditya.fefo.infrastructure;
import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.data.redis.core.script.DefaultRedisScript; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.time.Duration; import java.util.*;
@Service public class RedisLockService { private final StringRedisTemplate redis; private final long ttl; private final DefaultRedisScript<Long> release=new DefaultRedisScript<>("if redis.call('get',KEYS[1]) == ARGV[1] then return redis.call('del',KEYS[1]) else return 0 end",Long.class); public RedisLockService(StringRedisTemplate redis,@Value("${app.lock.ttl-ms}") long ttl){this.redis=redis;this.ttl=ttl;} public LockHandle acquire(String key,Duration wait)throws InterruptedException{String token=UUID.randomUUID().toString();long deadline=System.nanoTime()+wait.toNanos();while(System.nanoTime()<deadline){Boolean ok=redis.opsForValue().setIfAbsent(key,token,Duration.ofMillis(ttl));if(Boolean.TRUE.equals(ok))return new LockHandle(this,key,token);Thread.sleep(25);}throw new IllegalStateException("Could not acquire distributed lock");} private void release(String key,String token){redis.execute(release,List.of(key),token);} public static final class LockHandle implements AutoCloseable {private final RedisLockService owner;private final String key;private final String token;private boolean closed;private LockHandle(RedisLockService o,String k,String t){owner=o;key=k;token=t;} @Override public void close(){if(!closed){closed=true;owner.release(key,token);}}}}
